<?php
require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/session.php';require_once __DIR__.'/../../includes/functions.php';require_once __DIR__.'/../../includes/admin_layout.php';if(!is_admin_logged_in())redirect('../../index.php');if(($_SESSION['admin_role']??'admin')!=='admin'){http_response_code(403);exit('Administrator access required.');}if($_SERVER['REQUEST_METHOD']==='POST'&&verify_csrf_token($_POST['csrf_token']??'')){pg_query_params($conn,'INSERT INTO player_assignments(attendee_id,event_id,sport,team,player_position) VALUES($1,$2,$3,$4,$5) ON CONFLICT DO NOTHING',[(int)$_POST['attendee_id'],(int)$_POST['event_id'],trim($_POST['sport']),trim($_POST['team']),trim($_POST['player_position'])]);redirect('index.php');}$students=pg_query($conn,"SELECT id,attendee_code,full_name FROM attendees WHERE status='active' ORDER BY full_name");$events=pg_query($conn,'SELECT id,title FROM events ORDER BY start_at DESC');$rows=pg_query($conn,"SELECT p.*,a.attendee_code,a.full_name,e.title,(SELECT COUNT(*) FROM session_attendance sa JOIN event_registrations r ON r.id=sa.registration_id JOIN event_sessions s ON s.id=sa.session_id WHERE r.attendee_id=a.id AND s.event_id=e.id AND sa.time_in_at IS NOT NULL) sessions_attended FROM player_assignments p JOIN attendees a ON a.id=p.attendee_id JOIN events e ON e.id=p.event_id ORDER BY e.start_at DESC,p.sport,p.team,a.full_name");admin_page_start('Players','players');?>
<div class="hero"><div><h2><i class="fas fa-trophy"></i> Event Players</h2><p>Identify athletes by event, sport, and team while monitoring their attendance.</p></div></div><div class="card"><form method="post" class="form-grid"><?=csrf_field()?><div class="field"><label>Student</label><select name="attendee_id"><?php while($s=pg_fetch_assoc($students)):?><option value="<?=(int)$s['id']?>"><?=h($s['attendee_code'].' · '.$s['full_name'])?></option><?php endwhile;?></select></div><div class="field"><label>Event</label><select name="event_id"><?php while($e=pg_fetch_assoc($events)):?><option value="<?=(int)$e['id']?>"><?=h($e['title'])?></option><?php endwhile;?></select></div><div class="field"><label>Sport / Game</label><input name="sport" required></div><div class="field"><label>Team</label><input name="team"></div><div class="field full"><label>Player position</label><input name="player_position"></div><div class="field full"><button class="btn">Add Player</button></div></form></div><div class="card"><table><thead><tr><th>Player</th><th>Event</th><th>Sport / Team</th><th>Position</th><th>Sessions Attended</th></tr></thead><tbody><?php while($p=pg_fetch_assoc($rows)):?><tr><td><strong><?=h($p['full_name'])?></strong><div class="help"><?=h($p['attendee_code'])?></div></td><td><?=h($p['title'])?></td><td><?=h($p['sport'].' · '.$p['team'])?></td><td><?=h($p['player_position']?:'—')?></td><td><?=(int)$p['sessions_attended']?></td></tr><?php endwhile;?></tbody></table></div><?php admin_page_end();?>
